#include "news_store.hpp"
#include <QSqlDatabase>
#include <QSqlQuery>
#include <QJsonDocument>
#include <QFileInfo>
#include <QDir>
#include <QUuid>
#include <QTemporaryFile>
#include <QRegularExpression>
#include <stdexcept>
namespace publicNews {namespace {
void need(bool b,const char* why="资讯库操作失败；原记录保留"){if(!b)throw std::runtime_error(why);}
void active(const Cancel& cancel){need(!cancel||!cancel(),"资讯操作已取消");}
qint64 scalar(QSqlDatabase& db,QString sql){QSqlQuery q(db);need(q.exec(sql)&&q.next());return q.value(0).toLongLong();}
void exec(QSqlDatabase& db,QString sql){QSqlQuery q(db);need(q.exec(sql));}
struct Connection {QString name=QUuid::createUuid().toString();QSqlDatabase db=QSqlDatabase::addDatabase("QSQLITE",name);Connection(QString file,bool write,const Cancel& cancel){try{active(cancel);if(write&&!QFileInfo::exists(file))need(QDir().mkpath(QFileInfo(file).absolutePath()));db.setDatabaseName(file);db.setConnectOptions(write?"QSQLITE_BUSY_TIMEOUT=100":"QSQLITE_OPEN_READONLY;QSQLITE_BUSY_TIMEOUT=100");need(db.open());auto app=scalar(db,"PRAGMA application_id");need(app==0x4e575631||(write&&app==0&&scalar(db,"SELECT count(*) FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")==0),"不是资讯专用库，未改动");need(scalar(db,"PRAGMA user_version")<=1,"资讯库版本高于程序");if(write){exec(db,"PRAGMA synchronous=FULL");need(db.transaction());try{exec(db,"CREATE TABLE IF NOT EXISTS records(key TEXT PRIMARY KEY,digest TEXT NOT NULL,payload BLOB NOT NULL)");exec(db,"CREATE TABLE IF NOT EXISTS imports(digest TEXT PRIMARY KEY,applied_at TEXT NOT NULL)");exec(db,"PRAGMA application_id="+QString::number(0x4e575631));exec(db,"PRAGMA user_version=1");active(cancel);need(db.commit());}catch(...){db.rollback();throw;}}}catch(...){close();throw;}}void close(){db.close();db={};QSqlDatabase::removeDatabase(name);}~Connection(){close();}};
struct Transaction {QSqlDatabase& db;bool committed=false;explicit Transaction(QSqlDatabase& db):db(db){need(db.transaction());}~Transaction(){if(!committed)db.rollback();}void commit(const Cancel& cancel){active(cancel);need(db.commit());committed=true;}};
QJsonObject record(QSqlDatabase& db,QString key,const Cancel& cancel){active(cancel);QSqlQuery q(db);q.prepare("SELECT length(payload),digest FROM records WHERE key=?");q.addBindValue(key);need(q.exec());if(!q.next())return {};auto length=q.value(0).toLongLong();auto digest=q.value(1).toString();need(length>0&&length<=maxBytes,"资讯长度无效");q.finish();QByteArray bytes;bytes.reserve(int(length));for(int start=1;start<=length;start+=65536){active(cancel);q.prepare("SELECT substr(payload,?,65536) FROM records WHERE key=?");q.addBindValue(start);q.addBindValue(key);need(q.exec()&&q.next());auto part=q.value(0).toByteArray();need(part.size()==std::min<qint64>(65536,length-start+1),"资讯分块长度不符");bytes.append(part);q.finish();}need(bytes.size()==length&&hash(bytes)==digest,"资讯摘要不符");QJsonParseError error;auto doc=QJsonDocument::fromJson(bytes,&error);need(error.error==QJsonParseError::NoError&&doc.isObject(),"资讯JSON损坏");return doc.object();}
void put(QSqlDatabase& db,QString key,QJsonObject data,const Cancel& cancel){active(cancel);auto bytes=QJsonDocument(data).toJson(QJsonDocument::Compact);need(!bytes.isEmpty()&&bytes.size()<=maxBytes,"资讯保存超过8MiB，不截断");QSqlQuery q(db);q.prepare("INSERT OR REPLACE INTO records(key,digest,payload) VALUES(?,?,?)");q.addBindValue(key);q.addBindValue(hash(bytes));q.addBindValue(bytes);need(q.exec());need(record(db,key,cancel)==data,"资讯写后读回不符");}
QJsonObject archive(QSqlDatabase& db,const Cancel& cancel){auto a=record(db,"archive",cancel);if(a.isEmpty())return empty();validateArchive(a);return a;}
QJsonObject writeArchive(QSqlDatabase& db,QJsonObject input,qint64 expected,const Cancel& cancel){validateArchive(input);need(expected>=0&&expected<9007199254740991LL&&archive(db,cancel)["revision"].toDouble()==expected,"本机资讯档案已被修改，请重读后保存");input["revision"]=double(expected+1);input["savedAt"]=time(QDateTime::currentDateTimeUtc());validateArchive(input);put(db,"archive",input,cancel);return input;}
}
QJsonObject Store::archive(const Cancel& cancel)const{active(cancel);if(!QFileInfo::exists(file))return empty();Connection c(file,false,cancel);return publicNews::archive(c.db,cancel);}
QJsonObject Store::saveArchive(QJsonObject input,qint64 expected,const Cancel& cancel)const{validateArchive(input);Connection c(file,true,cancel);Transaction tx(c.db);auto next=writeArchive(c.db,input,expected,cancel);tx.commit(cancel);return next;}
QJsonObject Store::importPreview(QJsonObject p,const Cancel& cancel)const{validateArchive(p["archive"].toObject());auto digest=p["digest"].toString();need(QRegularExpression("^[0-9a-f]{64}$").match(digest).hasMatch(),"导入摘要无效");Connection c(file,true,cancel);Transaction tx(c.db);QSqlQuery q(c.db);q.prepare("SELECT 1 FROM imports WHERE digest=?");q.addBindValue(digest);need(q.exec());if(q.next()){auto a=publicNews::archive(c.db,cancel);q.finish();tx.commit(cancel);return a;}q.finish();auto next=writeArchive(c.db,p["archive"].toObject(),qint64(p["expectedRevision"].toDouble(-1)),cancel);q.prepare("INSERT INTO imports(digest,applied_at) VALUES(?,?)");q.addBindValue(digest);q.addBindValue(time(QDateTime::currentDateTimeUtc()));need(q.exec());tx.commit(cancel);return next;}
QJsonObject Store::cache(QJsonObject query,const Cancel& cancel)const{auto key=queryKey(query);active(cancel);if(!QFileInfo::exists(file))return {};Connection c(file,false,cancel);QJsonObject out;auto snapshot=record(c.db,"cache:"+key,cancel),attempt=record(c.db,"attempt:"+key,cancel);if(!snapshot.isEmpty()){validateSnapshot(snapshot);need(snapshot["key"]==key&&snapshot["complete"].toBool(),"不是当前范围完整资讯缓存");out["snapshot"]=snapshot;}if(!attempt.isEmpty())out["attempt"]=attempt;return out;}
void Store::saveSnapshot(QJsonObject snapshot,const Cancel& cancel)const{validateSnapshot(snapshot);need(snapshot["complete"].toBool(),"部分资讯不覆盖旧完整缓存");auto key=snapshot["key"].toString();Connection c(file,true,cancel);Transaction tx(c.db);auto prior=record(c.db,"cache:"+key,cancel);need(prior.isEmpty()||QDateTime::fromString(snapshot["fetchedAt"].toString(),Qt::ISODateWithMs)>=QDateTime::fromString(prior["fetchedAt"].toString(),Qt::ISODateWithMs),"旧回调不能覆盖新集合");put(c.db,"cache:"+key,snapshot,cancel);put(c.db,"attempt:"+key,{{"checkedAt",snapshot["fetchedAt"]},{"error",""},{"status","complete-requested-range"}},cancel);tx.commit(cancel);}
void Store::failure(QJsonObject query,QString message,const Cancel& cancel)const{need(!message.isEmpty()&&message.size()<=4000,"失败信息无效");auto key=queryKey(query);Connection c(file,true,cancel);Transaction tx(c.db);put(c.db,"attempt:"+key,{{"checkedAt",time(QDateTime::currentDateTimeUtc())},{"error",message},{"status","source-unavailable"}},cancel);tx.commit(cancel);}
QJsonObject Store::article(QJsonObject item,const Cancel& cancel)const{validateItem(item);active(cancel);if(!QFileInfo::exists(file))return {};Connection c(file,false,cancel);QJsonObject out;auto data=record(c.db,"article:"+item["id"].toString(),cancel),attempt=record(c.db,"article-attempt:"+item["id"].toString(),cancel);if(!data.isEmpty()){need(data["itemId"]==item["id"],"缓存正文身份不符");validateArticle(data["article"].toObject(),item);out["article"]=data["article"];}if(!attempt.isEmpty())out["attempt"]=attempt;return out;}
void Store::saveArticle(QJsonObject item,QJsonObject article,const Cancel& cancel)const{validateItem(item);validateArticle(article,item);auto id=item["id"].toString();Connection c(file,true,cancel);Transaction tx(c.db);if(article["status"]=="available")put(c.db,"article:"+id,{{"itemId",id},{"article",article}},cancel);put(c.db,"article-attempt:"+id,{{"checkedAt",article["fetchedAt"]},{"error",article["status"]=="available"?QJsonValue(""):article["message"]},{"status",article["status"]}},cancel);tx.commit(cancel);}
void exportNew(QByteArray bytes,QString path,const Cancel& cancel){active(cancel);QFileInfo target(path);need(!target.exists()&&!target.isSymLink()&&QFileInfo(target.absolutePath()).isDir(),"仅读写新导出目标，不覆盖既有文件");QTemporaryFile temp(target.absolutePath()+"/.news-export-XXXXXX");need(temp.open()&&temp.write(bytes)==bytes.size()&&temp.flush(),"资讯导出失败");temp.close();active(cancel);need(!QFileInfo::exists(path)&&temp.rename(target.absoluteFilePath()),"导出目标已存在或发布失败");temp.setAutoRemove(false);}
}
